export const NAVIGATION_FEATURE_COUNT=500;
export const navigationSnapshot=(state={})=>{const p=state.navigationProgress||{};const verified=Object.values(p).filter(v=>v==="verified").length;const building=Object.values(p).filter(v=>v==="building").length;return {total:500,verified,building,pending:500-verified-building};};
export const setNavigationFeatureState=(state,id,status)=>({...state,navigationProgress:{...(state.navigationProgress||{}),[id]:status}});
const norm=v=>String(v??"").toLowerCase().replace(/[.,!?;:()[\]{}]/g," ").replace(/\s+/g," ").trim();
const subjectMap=[["mathematics","math"],["math","math"],["physics","physics"],["chemistry","chemistry"],["biology","biology"],["agriculture","agriculture"],["english","english"],["information technology","it"],["it","it"],["web design","web design"]];
const numWord={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,eleven:11,twelve:12};
const captureNum=(x,re)=>{const m=x.match(re);if(!m)return null;return numWord[m[1]]||Number(m[1])||null};
export function navigationIntent(message,state={}){
 const x=norm(message);
 const n={message:String(message||""),action:/\b(search|find|look for)\b/.test(x)?"search":/\b(play|watch)\b/.test(x)?"play":"open",destination:null,video:/\b(video|watch|lesson|tutorial|lecture)\b/.test(x),grade:captureNum(x,/\b(?:grade|class|year|form|standard)\s*(\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b/),chapter:captureNum(x,/\b(?:chapter|ch)\s*(\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b/),unit:captureNum(x,/\bunit\s*(\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b/),subject:null,topic:null,contextual:false,query:x};
 if(/\b(?:futurex|future x)\b/.test(x))n.destination="futurex";
 else if(/\b(?:youtube|you tube)\b/.test(x))n.destination="youtube";
 else if(/\b(?:browser|web|website|google|internet)\b/.test(x))n.destination="web";
 for(const [label,value] of subjectMap)if(x.includes(label)){n.subject=value;break}
 const topic=x.match(/\b(?:about|topic)\s+(.+?)(?:\s+on\s+(?:futurex|youtube|the web))?$/);
 if(topic)n.topic=topic[1].trim();
 if(/\b(?:related|recommended|next|current|weakest|that|this|there|it)\b/.test(x))n.contextual=true;
 return n;
}
export function navigationContext(state={}){
 const active=state.active||{};
 const snap=state.academic||{};
 const weak=snap.weak?.[0];
 return {grade:state.grade||state.profile?.grade||12,subject:active.subject||weak?.subject||null,topic:active.topic||weak?.topic||null,active,mastery:state.mastery||{},plans:state.plans||[],lastNavigation:state.lastNavigation||null};
}
export function buildNavigationTarget(intent,state={}){
 const ctx=navigationContext(state);
 if(intent.contextual){if(!intent.grade)intent.grade=ctx.grade;if(!intent.subject)intent.subject=ctx.subject;if(!intent.topic&&ctx.topic)intent.topic=ctx.topic}
 const q=[intent.grade&&("grade "+intent.grade),intent.subject,intent.chapter&&("chapter "+intent.chapter),intent.unit&&("unit "+intent.unit),intent.topic].filter(Boolean).join(" ");
 const query=(q||intent.query||"educational video").trim();
 if(intent.destination==="futurex")return {type:"app",destination:"futurex",packageName:"com.inspireethiopia.net.futurexappversion2",query,deepLink:null,deepLinkVerified:false,fallbackUrl:"https://www.google.com/search?q="+encodeURIComponent("FutureX "+query)};
 if(intent.destination==="youtube"||intent.video)return {type:"external",destination:"youtube",url:"https://www.youtube.com/results?search_query="+encodeURIComponent(query),query};
 if(intent.destination==="web")return {type:"external",destination:"web",url:"https://www.google.com/search?q="+encodeURIComponent(query),query};
 return {type:"external",destination:"youtube",url:"https://www.youtube.com/results?search_query="+encodeURIComponent(query),query};
}
export function navigationDecision(intent){return {allowed:Boolean(intent.message?.trim()),needsContext:Boolean(intent.contextual&&!intent.subject&&!intent.topic&&!intent.chapter&&!intent.grade),destination:intent.destination||"auto"};}
export function resolveNavigation(message,state={}){const intent=navigationIntent(message,state);const target=buildNavigationTarget(intent,state);return {intent,decision:navigationDecision(intent),target};}
export function recordNavigation(state,target,result="requested"){const item={target,result,time:Date.now()};return {...state,lastNavigation:item,navigationHistory:[...(state.navigationHistory||[]),item].slice(-50)};}
